mapper.select:
select id, metric_category, metric_name, metric_scope, metric_value, metric_unit, tag_json,
       service_id, service_ip_port, sample_time, create_time
from monitor_metric_sample
where metric_category = #{category}
and sample_time >= #{beginTime}
and sample_time <= #{endTime}

    and service_id = #{serviceId}


    and service_ip_port = #{serviceIpPort}


    and metric_name in

        #{metricName}


order by sample_time asc

    limit #{limit}

select id, metric_category, metric_name, metric_scope, metric_value, metric_unit, tag_json,
       service_id, service_ip_port, sample_time, create_time
from monitor_metric_sample
where metric_category = #{category}
  and sample_time = (
      select max(sample_time) from monitor_metric_sample
      where metric_category = #{category}

          and service_id = #{serviceId}

              and service_ip_port = #{serviceIpPort}


  )

    and service_id = #{serviceId}

        and service_ip_port = #{serviceIpPort}

select t1.id, t1.metric_category, t1.metric_name, t1.metric_scope, t1.metric_value, t1.metric_unit, t1.tag_json,
       t1.service_id, t1.service_ip_port, t1.sample_time, t1.create_time
from monitor_metric_sample t1
inner join (
    select metric_category, metric_name, metric_scope, max(sample_time) as max_time
    from monitor_metric_sample


            and service_id = #{serviceId}

                and service_ip_port = #{serviceIpPort}



    group by metric_category, metric_name, metric_scope
) t2 on t1.metric_category = t2.metric_category
    and t1.metric_name = t2.metric_name
    and t1.metric_scope = t2.metric_scope
    and t1.sample_time = t2.max_time


        and t1.service_id = #{serviceId}

            and t1.service_ip_port = #{serviceIpPort}
